for m in range(NumMachinesTypes):
    for i in range(NumPeriods):
        model.addConstr(gurobipy.quicksum(Time[k][m] * Manufacture[k][i] for k in range(NumProducts)) <= NumWorkHours * 24 * (NumMachines[m] - Maintain[m][i]), name=f"MachineCapacity_{m}_{i}")

for k in range(NumProducts):
    for i in range(NumPeriods):
        model.addConstr(Sell[k][i] <= Limit[k][i], name=f"SalesLimit_{k}_{i}")

for k in range(NumProducts):
    for i in range(NumPeriods):
        model.addConstr(Store[k][i] <= 100, name=f"StorageLimit_{k}_{i}")

for k in range(NumProducts):
    for i in range(NumPeriods):
        if i == 0:
            model.addConstr(Store[k][i] == Manufacture[k][i] - Sell[k][i], name=f"Balance_{k}_{i}")
        else:
            model.addConstr(Store[k][i] == Store[k][i-1] + Manufacture[k][i] - Sell[k][i], name=f"Balance_{k}_{i}")

for k in range(NumProducts):
    for i in range(NumPeriods):
        model.addConstr(Sell[k][i] >= 0, name=f"NonNegSell_{k}_{i}")
        model.addConstr(Manufacture[k][i] >= 0, name=f"NonNegMfg_{k}_{i}")
        model.addConstr(Store[k][i] >= 0, name=f"NonNegStore_{k}_{i}")
